test('invoiceTotals with created invoice with discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 5 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const devHourTotal = 10 * 9500;
  const logoPackTotal = 1 * 120000;
  const expectedSubtotal = devHourTotal + logoPackTotal;
  const expectedDiscount = Math.round((devHourTotal * 10) / 100) + Math.round((logoPackTotal * 5) / 100);
  const devHourAmount = devHourTotal - Math.round((devHourTotal * 10) / 100);
  const logoPackAmount = logoPackTotal - Math.round((logoPackTotal * 5) / 100);
  const expectedVat = Math.round((devHourAmount * 21) / 100) + Math.round((logoPackAmount * 21) / 100);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedSubtotal - expectedDiscount + expectedVat);
});

