  const amount = 100000 - 10000;
  const expected = Math.round((amount * 21) / 100);
  assert.equal(vat, expected);
});

test('lineVat handles different VAT rates', () => {
  const line21 = { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const line9 = { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 9 };
  const line0 = { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 };

  assert.equal(lineVat(line21), 21000);
  assert.equal(lineVat(line9), 9000);
  assert.equal(lineVat(line0), 0);
});

test('lineVat is clamped to 0', () => {
  const line = { qty: 0, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  assert.equal(lineVat(line), 0);
});

test('invoiceTotals calculates VAT correctly', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const subtotal = 100 * 9500;
  const vat = Math.round((subtotal * 21) / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal + vat);
});

test('invoiceTotals with mixed VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 100 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const devTotal = 100 * 9500;
  const printTotal = 100 * 37;
  const devVat = Math.round((devTotal * 21) / 100);
  const printVat = Math.round((printTotal * 9) / 100);
  assert.equal(totals.subtotal, devTotal + printTotal);
  assert.equal(totals.vat, devVat + printVat);
  assert.equal(totals.total, devTotal + printTotal + devVat + printVat);
});

test('invoiceTotals VAT calculated after discount', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const subtotal = 100 * 9500;
  const discount = Math.round((subtotal * 10) / 100);
  const amount = subtotal - discount;
  const vat = Math.round((amount * 21) / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, amount + vat);
});

